create table if not exists public.setc_insurance_readiness_assessments (readiness_assessment_id uuid primary key default gen_random_uuid(),organization_oid text not null references public.setc_organizations(oid),release_reference text not null,environment_code text not null,assessment_status text not null default 'draft' check(assessment_status in ('draft','in_review','blocked','evidence_supported','ready_reference','not_ready_reference','superseded','void')),evidence_ref text,assessed_at timestamptz,created_at timestamptz not null default now(),unique(organization_oid,release_reference,environment_code),check(assessment_status not in ('evidence_supported','ready_reference','not_ready_reference') or evidence_ref is not null)); create table if not exists public.setc_insurance_readiness_controls (readiness_control_id uuid primary key default gen_random_uuid(),control_code text not null unique,control_name text not null,control_class text not null check(control_class in ('schema','migration','security','rls','grants','testing','performance','backup','rollback','recovery','observability','runbook','ownership','dependency','regulatory_authority','data_quality','other')),control_status text not null default 'active' check(control_status in ('active','superseded','retired','void')),evidence_requirement text,created_at timestamptz not null default now()); create table if not exists public.setc_insurance_readiness_results (readiness_result_id uuid primary key default gen_random_uuid(),readiness_assessment_id uuid not null references public.setc_insurance_readiness_assessments(readiness_assessment_id),readiness_control_id uuid not null references public.setc_insurance_readiness_controls(readiness_control_id),result_status text not null default 'not_run' check(result_status in ('not_run','running','passed_reference','failed_reference','blocked_reference','not_applicable_reference','superseded','void')),result_reference text,evidence_ref text,executed_at timestamptz,created_at timestamptz not null default now(),unique(readiness_assessment_id,readiness_control_id),check(result_status not in ('passed_reference','failed_reference','blocked_reference','not_applicable_reference') or evidence_ref is not null)); create table if not exists public.setc_insurance_recovery_readiness (recovery_readiness_id uuid primary key default gen_random_uuid(),readiness_assessment_id uuid not null references public.setc_insurance_readiness_assessments(readiness_assessment_id),recovery_type text not null check(recovery_type in ('rollback','backup_restore','point_in_time_recovery','failover','incident_response','business_continuity','other')),procedure_reference text not null,test_status text not null default 'untested' check(test_status in ('untested','tested_reference','failed_reference','not_applicable_reference','superseded','void')),last_tested_at timestamptz,evidence_ref text,created_at timestamptz not null default now(),unique(readiness_assessment_id,recovery_type,procedure_reference),check(test_status not in ('tested_reference','failed_reference','not_applicable_reference') or evidence_ref is not null)); create table if not exists public.setc_insurance_operational_readiness (operational_readiness_id uuid primary key default gen_random_uuid(),readiness_assessment_id uuid not null references public.setc_insurance_readiness_assessments(readiness_assessment_id),readiness_type text not null check(readiness_type in ('runbook','owner','on_call','monitoring','alerting','support','vendor_dependency','external_authority','data_feed','other')),reference_value text not null,status text not null default 'unverified' check(status in ('unverified','evidence_supported','verified_reference','blocked_reference','superseded','void')),evidence_ref text,created_at timestamptz not null default now(),check(status not in ('evidence_supported','verified_reference','blocked_reference') or evidence_ref is not null)); create table if not exists public.setc_insurance_go_live_decisions (go_live_decision_id uuid primary key default gen_random_uuid(),readiness_assessment_id uuid not null references public.setc_insurance_readiness_assessments(readiness_assessment_id),decision text not null check(decision in ('pending','go_reference','no_go_reference','conditional_go_reference','rollback_reference','superseded','void')),decision_reference text,decision_authority_reference text,evidence_ref text,decided_at timestamptz,created_at timestamptz not null default now(),check(decision in ('pending','superseded','void') or (decision_reference is not null and decision_authority_reference is not null and evidence_ref is not null))); create table if not exists public.setc_insurance_post_deployment_verifications (post_deployment_verification_id uuid primary key default gen_random_uuid(),readiness_assessment_id uuid not null references public.setc_insurance_readiness_assessments(readiness_assessment_id),verification_type text not null check(verification_type in ('schema','migration','security','rls','grants','smoke_test','performance','observability','data_integrity','incident','rollback','other')),verification_status text not null default 'pending' check(verification_status in ('pending','passed_reference','failed_reference','blocked_reference','superseded','void')),verification_reference text,evidence_ref text,verified_at timestamptz,created_at timestamptz not null default now(),check(verification_status not in ('passed_reference','failed_reference','blocked_reference') or evidence_ref is not null)); create index if not exists idx_ins_ready_assessment_org on public.setc_insurance_readiness_assessments(organization_oid); create index if not exists idx_ins_ready_result_assessment on public.setc_insurance_readiness_results(readiness_assessment_id); create index if not exists idx_ins_ready_result_control on public.setc_insurance_readiness_results(readiness_control_id); create index if not exists idx_ins_recovery_assessment on public.setc_insurance_recovery_readiness(readiness_assessment_id); create index if not exists idx_ins_operational_assessment on public.setc_insurance_operational_readiness(readiness_assessment_id); create index if not exists idx_ins_golive_assessment on public.setc_insurance_go_live_decisions(readiness_assessment_id); create index if not exists idx_ins_postdeploy_assessment on public.setc_insurance_post_deployment_verifications(readiness_assessment_id); alter table public.setc_insurance_readiness_assessments enable row level security; alter table public.setc_insurance_readiness_controls enable row level security; alter table public.setc_insurance_readiness_results enable row level security; alter table public.setc_insurance_recovery_readiness enable row level security; alter table public.setc_insurance_operational_readiness enable row level security; alter table public.setc_insurance_go_live_decisions enable row level security; alter table public.setc_insurance_post_deployment_verifications enable row level security; revoke all privileges on public.setc_insurance_readiness_assessments,public.setc_insurance_readiness_controls,public.setc_insurance_readiness_results,public.setc_insurance_recovery_readiness,public.setc_insurance_operational_readiness,public.setc_insurance_go_live_decisions,public.setc_insurance_post_deployment_verifications from anon,authenticated; grant all privileges on public.setc_insurance_readiness_assessments,public.setc_insurance_readiness_controls,public.setc_insurance_readiness_results,public.setc_insurance_recovery_readiness,public.setc_insurance_operational_readiness,public.setc_insurance_go_live_decisions,public.setc_insurance_post_deployment_verifications to service_role; comment on table public.setc_insurance_go_live_decisions is 'Governance/evidence record only; does not create insurance licensing, regulatory approval, coverage, capital adequacy, or operational guarantees.';
